{
  "findings": [
    {
      "check_id": "CKV_AWS_126",
      "title": "EC2 detailed monitoring is disabled",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The instance does not enable detailed monitoring, reducing the granularity of operational telemetry available for detecting anomalous behavior and investigating incidents."
    },
    {
      "check_id": "CKV_AWS_135",
      "title": "EC2 instance is not EBS optimized",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The instance does not enable EBS optimization, which can reduce storage performance predictability and resilience under load."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Instance Metadata Service v1 is enabled",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "No metadata options require session tokens, so the instance permits IMDSv1 and is more susceptible to metadata credential theft through SSRF-style attacks."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "EC2 root EBS volume encryption is not enforced",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The root block device does not explicitly enable encryption, so data stored on the instance root volume may be unencrypted at rest depending on account defaults and the selected AMI."
    },
    {
      "check_id": "CKV2_AWS_41",
      "title": "EC2 instance has no IAM role",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The instance has no IAM instance profile, preventing workloads from using short-lived role credentials if AWS API access is required and increasing the risk that long-lived credentials are used instead."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"web\" {\n  ami                    = \"${var.ami}\"\n  instance_type          = \"t3.micro\"\n  subnet_id              = \"${aws_subnet.public-subnet.id}\"\n  vpc_security_group_ids = [\"${aws_security_group.sgweb.id}\"]\n  monitoring             = true\n  ebs_optimized          = true\n  iam_instance_profile   = aws_iam_instance_profile.web.name\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n}\n\nresource \"aws_iam_role\" \"web\" {\n  name_prefix = \"web-\"\n\n  assume_role_policy = jsonencode({\n    Version = \"2012-10-17\"\n    Statement = [\n      {\n        Effect = \"Allow\"\n        Principal = {\n          Service = \"ec2.amazonaws.com\"\n        }\n        Action = \"sts:AssumeRole\"\n      }\n    ]\n  })\n}\n\nresource \"aws_iam_instance_profile\" \"web\" {\n  name_prefix = \"web-\"\n  role        = aws_iam_role.web.name\n}\n",
  "fix_summary": "Enabled detailed monitoring, EBS optimization, IMDSv2 enforcement, and root-volume encryption. Changed the unsupported EBS-optimization configuration from t2.micro to the comparable t3.micro type and attached a permissionless EC2 IAM role through an instance profile."
}
